(18894, '_iss_editorial_publication', '{"schema_version":1,"skin":"bildmatrix","variant":"standard","features":[],"sections":[{"type":"intro","kicker":"Fotoalbum","title":"Album und Kontext","body":"Das im August 1945 von den Sowjets gegründete LKVO (Labor-, Konstruktions- und Versuchswerk Oberspree) diente vorwiegend der Vermittlung elektrotechnischen Know-hows und der Nachentwicklung von Elektronenröhren für den sowjetischen Markt. Im Juli 1946 erfolgte die Umbenennung in Oberspreewerk; das Album entstand vermutlich für sowjetische Vorgesetzte im LKVO und dokumentiert den Betrieb in 52 Fotografien."},{"type":"publication_rail","kicker":"Album","title":"Albumnavigation","body":"","rail_options":{"show_nav":false,"show_summary":false,"show_related":false,"variant":"detailed"}},{"type":"source","kicker":"Quelle","title":"Kontext, Quelle und Rechte","body":"Diese digitale Edition übernimmt die vollständige Bildfolge der bereits vorhandenen WF-Ausgabe. Zur Quellseite: WF-Museum. Ausgangstext zum Kontext: Quellen zur Geschichte des WF – Folge 4.Quelle der Digitaledition: WF-Museum und Industriesalon Schöneweide. Die Bilddateien auf der Quellseite sind mit Industriesalon-Rechten als CC BY-SA ausgewiesen.","links":[{"label":"WF-Museum","url":"https://wf-museum.de/home-2/betriebsfotoalben/fotoalbum-labor-konstruktions-und-versuchswerk-oberspree-1946/"},{"label":"Quellen zur Geschichte des WF – Folge 4","url":"http://192.168.2.31:8082/archivbeitraege/quellen-zur-geschichte-des-wf-folge-4-fotoalben-aus-dem-wf/"}]},{"type":"photoalbum","kicker":"Album","title":"Fotoalbum Labor, Konstruktions- und Versuchswerk Oberspree, 1946","body":"","album_source":{"kind":"manual","set_id":"","set_title":"WF-Museum"},"sheets":[{"source_kind":"wp_media","source_id":"18895","visible":true,"label":"Blatt 01","nav_title":"Blatt 01","caption":"Titel Labor, Konstruktions- und Versuchswerk Oberspree, S.1 des Fotoalbums \\\\"Labor, Konstruktions- und Versuchswerk Oberspree\\\\" mit 52 Fotos mit russischer Beschriftung, Frühjahr 1946.","caption_override":"","thumbnail":"http://192.168.2.31:8082/wp-content/uploads/2026/05/ALB-001-1-1-150x150.jpg","position":1,"source_item_id":"0"},{"source_kind":"wp_media","source_id":"18896","visible":true,"label":"Blatt 02","nav_title":"Blatt 02","caption":"Hauptgebäude LKB (Labor- und Konstruktions- Büro), S.2 des Fotoalbums \\\\"Labor, Konstruktions- und Versuchswerk Oberspree\\\\" mit 52 Fotos mit russischer Beschriftung, Frühjahr 1946.","caption_override":"","thumbnail":"http://192.168.2.31:8082/wp-content/uploads/2026/05/ALB-001-2-1-150x150.jpg","position":2,"source_item_id":"0"},{"source_kind":"wp_media","source_id":"18897","visible":true,"label":"Blatt 03","nav_title":"Blatt 03","caption":"Neuer Flügel LKB, S.3 des Fotoalbums \\\\"Labor, Konstruktions- und Versuchswerk Oberspree\\\\" mit 52 Fotos mit russischer Beschriftung, Frühjahr 1946.","caption_override":"","thumbnail":"http://192.168.2.31:8082/wp-content/uploads/2026/05/ALB-001-3-1-150x150.jpg","position":3,"source_item_id":"0"},{"source_kind":"wp_media","source_id":"18898","visible":true,"label":"Blatt 04","nav_title":"Blatt 04","caption":"Konstruktionsbüro, S.4 des Fotoalbums \\\\"Labor, Konstruktions- und Versuchswerk Oberspree\\\\" mit 52 Fotos mit russischer Beschriftung, Frühjahr 1946.","caption_override":"","thumbnail":"http://192.168.2.31:8082/wp-content/uploads/2026/05/ALB-001-4-1-150x150.jpg","position":4,"source_item_id":"0"},{"source_kind":"wp_media","source_id":"18899","visible":true,"label":"Blatt 05","nav_title":"Blatt 05","caption":"Vorrichtungswerkstatt, S.5 des Fotoalbums \\\\"Labor, Konstruktions- und Versuchswerk Oberspree\\\\" mit 52 Fotos mit russischer Beschriftung, Frühjahr 1946.","caption_override":"","thumbnail":"http://192.168.2.31:8082/wp-content/uploads/2026/05/ALB-001-5-1-150x150.jpg","position":5,"source_item_id":"0"},{"source_kind":"wp_media","source_id":"18900","visible":true,"label":"Blatt 06","nav_title":"Blatt 06","caption":"W